"use client"

import { useMemo, useState } from "react"
import ArrowLeft from "@/components/icons/ArrowLeft"
import PrimaryButton from "@/components/buttons/PrimaryButton"

type Props = {
  backHref: string
  nextHref: string
  businessName?: string
  title?: string
  maxPastVends?: number
}

export default function PrevConsCard({
  backHref,
  nextHref,
  title = "Tell us where you’ve been!",
  maxPastVends = 4,
}: Props) {
  const [firstVend, setFirstVend] = useState(false)
  const [input, setInput] = useState("")
  const [vends, setVends] = useState<string[]>([])

  const remaining = maxPastVends - vends.length
  const canAdd = !firstVend && input.trim().length > 0 && vends.length < maxPastVends

  const canContinue = useMemo(() => {
    return firstVend || vends.length > 0
  }, [firstVend, vends.length])

  function addVend() {
    const trimmed = input.trim()
    if (!trimmed) return
    if (vends.length >= maxPastVends) return
    if (vends.some((v) => v.toLowerCase() === trimmed.toLowerCase())) {
      setInput("")
      return
    }
    setVends((prev) => [...prev, trimmed])
    setInput("")
  }

  function onKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter") {
      e.preventDefault()
      addVend()
    }
  }

  function toggleFirstVend() {
    setFirstVend((prev) => {
      const next = !prev
      if (next) {
        setInput("")
        setVends([])
      }
      return next
    })
  }

  return (
    <div
      className="
        relative
        w-[914px] h-[579px]
        flex flex-col justify-between items-center
        px-[45px] py-[50px]
        bg-white rounded-[15px]
        shadow-[8px_8px_50px_rgba(0,0,0,0.05)]
        max-w-[calc(100vw-40px)]
      "
    >
      {/* Back arrow */}
      <ArrowLeft href={backHref} className="absolute left-[45px] top-[50px]" />

      {/* Header */}
      <div className="w-full flex justify-center">
        <div className="relative w-[824px] h-[18px] flex items-start justify-center">
          <p className="m-0 font-inter font-normal text-[25px] leading-[30px] text-black text-center">
            {title}
          </p>
        </div>
      </div>

      {/* Middle block */}
      <div className="w-[436px] h-[276px] flex flex-col items-start gap-[30px]">
        {/* Input */}
        <div className="w-[436px] flex flex-col items-start gap-[8px]">
          <p className="m-0 w-full font-inter font-normal text-[16px] leading-[140%] text-[#1E1E1E]">
            Previous Vending
          </p>

          <p className="m-0 font-inter font-normal text-[12px] leading-[140%] text-[#A5A5A5]">
            Max {maxPastVends} past vends
          </p>

          <div className="w-[436px] h-[40px]">
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={onKeyDown}
              placeholder="Vended Event 2026"
              disabled={firstVend || vends.length >= maxPastVends}
              className={`
                w-full h-full
                px-[12px]
                bg-white
                border border-[#A5A5A5]/50
                rounded-[8px]
                font-inter font-normal text-[14px] leading-[140%]
                text-[#262626]
                placeholder:text-[#A5A5A5]
                outline-none
                ${firstVend ? "opacity-50 cursor-not-allowed" : ""}
              `}
            />
          </div>

          {/* Helper text (fixed height, prevents layout shift) */}
          <div className="h-[17px] mt-[2px]">
            {!firstVend && vends.length >= maxPastVends ? (
              <p className="m-0 font-inter text-[12px] leading-[140%] text-[#FF4603]">
                Limit reached
              </p>
            ) : !firstVend && input.trim() && remaining > 0 ? (
              <p className="m-0 font-inter text-[12px] leading-[140%] text-[#A5A5A5]">
                Press Enter to add ({remaining} left)
              </p>
            ) : (
              <span className="block h-full" aria-hidden="true" />
            )}
          </div>

          {/* Checkbox */}
          <button
            type="button"
            onClick={toggleFirstVend}
            className="mt-[6px] flex items-center gap-[7px] py-[5px]"
          >
            <span
              className={`
                w-[13px] h-[13px]
                rounded-[3.25px]
                border border-[#262626]
                grid place-items-center
              `}
              aria-hidden="true"
            >
              {firstVend && (
                <span className="w-[9px] h-[9px] bg-[#262626] rounded-[2px]" />
              )}
            </span>

            <span className="font-inter font-normal text-[12px] leading-[140%] text-[#A5A5A5]">
              I’m looking for my first vend.
            </span>
          </button>
        </div>

        {/* Previous vends */}
        <div className="w-[436px] flex flex-col items-center gap-[15px]">
          <p className="m-0 w-full text-center font-inter font-normal text-[13px] leading-[16px] text-[#A5A5A5]">
            Previous Vends
          </p>

          <div className="w-full flex flex-col items-center gap-[10px]">
            {vends.length === 0 ? (
              <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
                —
              </p>
            ) : (
              vends.map((v) => (
                <p
                  key={v}
                  className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#262626]"
                >
                  {v}
                </p>
              ))
            )}
          </div>
        </div>
      </div>

      {/* Next */}
      <PrimaryButton
        href={canContinue ? nextHref : "#"}
        className={!canContinue ? "pointer-events-none opacity-40" : ""}
      >
        Next
      </PrimaryButton>
    </div>
  )
}
